function getNumber(num = ""){
    if(!num) return 0;
    let number =[];
    for (let index = 0; index < num.length; index++) {
      if(/[0-9.]/.test(num[index])) number.push(num[index]); 
    }
    return Number(number.join(""))
     }
    
     function multiplyNumbers(amount, month){
     
        let total = `${getNumber(amount) * getNumber(month)}`
        console.log(total)
        return total
     }


